package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.service.BusinessException; import jakarta.validation.ConstraintViolationException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(BusinessException.class) ResponseEntity<?> business(BusinessException e){return ResponseEntity.status(e.status()).body(java.util.Map.of("mensaje",e.getMessage()));} @ExceptionHandler({ConstraintViolationException.class,org.springframework.web.bind.MethodArgumentNotValidException.class}) ResponseEntity<?> validation(Exception e){return ResponseEntity.badRequest().body(java.util.Map.of("mensaje","Datos de entrada no válidos."));} }
